typedef struct {
    int16_t x;
    int16_t y;
    uint8_t ref;
    uint8_t scale;
} MvField;

/* Simulates the vulnerable buffer pool initialization */
void init_buffer_pool(uint32_t min_pu_width, uint32_t min_pu_height) {
    /* Vulnerable: multiplication performed in 32-bit arithmetic */
    /* If dimensions are large, the product wraps around (overflows) */
    uint32_t min_pu_size = min_pu_width * min_pu_height;

    /* Size calculation also in 32-bit before conversion to size_t */
    uint32_t truncated_size = min_pu_size * sizeof(MvField);

    printf("[!] Calculated pool size: %u bytes (original dims: %u x %u)\n",
           truncated_size, min_pu_width, min_pu_height);

    /* Allocation uses the truncated/overflowed size */
    MvField *pool = malloc(truncated_size);
    if (!pool) return;

    /* Later decoding phase uses original large dimensions for indexing */
    /* This causes out-of-bounds heap writes when index exceeds allocated size */
    for (uint32_t y = 0; y < min_pu_height; y++) {
        for (uint32_t x = 0; x < min_pu_width; x++) {
            uint32_t idx = y * min_pu_width + x;
            pool[idx].x = 0; /* OOB write when idx >= truncated_size / sizeof(MvField) */
        }
    }

    free(pool);
}

