} RefPicListTab;

int main(void) {
    /* Malformed SPS parameter causes an abnormally large CTB count */
    uint32_t ctb_count = 0x10000000;

    /* 
     * VULNERABILITY: Integer overflow in size calculation.
     * The multiplication is implicitly or explicitly cast to 32-bit before
     * being passed to the allocator. This truncates the result.
     * 0x10000000 * 32 = 0x200000000 (33 bits) -> truncates to 0x00000000
     */
    uint32_t truncated_size = (uint32_t)(ctb_count * sizeof(RefPicListTab));

    printf("ctb_count: 0x%08X\n", ctb_count);
    printf("Actual required size: %zu bytes\n", (size_t)ctb_count * sizeof(RefPicListTab));
    printf("Truncated size passed to allocator: %u bytes\n", truncated_size);

    /* Allocator receives the truncated size, creating an undersized heap buffer */
    uint8_t *pool = malloc(truncated_size > 0 ? truncated_size : 1);
    if (!pool) return 1;

    /* 
     * EXPLOIT MECHANISM:
     * The decoder later iterates through ctb_count elements and writes
     * RefPicListTab structures into the pool. Since the pool was allocated
     * with the truncated size, these writes exceed the buffer bounds,
     * resulting in a heap buffer overflow.
     */
    size_t safe_capacity = (truncated_size > 0 ? truncated_size : 1) / sizeof(RefPicListTab);
    printf("Pool capacity: %zu elements\n", safe_capacity);
    printf("Decoder access count: %u elements\n", ctb_count);
    printf("Result: Heap buffer overflow when decoder writes beyond capacity.\n");

    free(pool);
    return 0;
}

