// Demonstrates the integer overflow vulnerability in allocation size calculation
void demonstrate_overflow(int alloc_size) {
    // Original vulnerable calculation uses signed 32-bit integers
    // 16 * 6 = 96. When alloc_size is large, this multiplication overflows.
    int wrapped_size = 16 * 6 * alloc_size; // Signed 32-bit overflow

    // Implicit conversion to size_t (unsigned) happens when passed to malloc
    // The wrapped signed value is reinterpreted as unsigned
    size_t alloc_size_t = (size_t)wrapped_size;

    printf("Input alloc_size: %d\n", alloc_size);
    printf("Calculated (int): %d\n", wrapped_size);
    printf("Allocated (size_t): %zu\n", alloc_size_t);

    // Allocate based on the truncated/wrapped size
    void *buf = malloc(alloc_size_t);
    if (!buf) return;

    // Subsequent decoding logic uses the original intended size
    // This mismatch causes a heap buffer overflow
    size_t intended_write = (size_t)16 * 6 * (size_t)alloc_size;
    printf("Intended write size: %zu\n", intended_write);
    printf("Vulnerability: %zu-byte write into %zu-byte buffer\n", intended_write, alloc_size_t);

    free(buf);
}

int main() {
    // Choose a value that causes the signed multiplication to wrap to a small positive number
    // 96 * X ≈ 2^32 + small_value => X ≈ 44739243
    int trigger_value = 44739243;
    printf("=== Integer Overflow POC ===\n");
    demonstrate_overflow(trigger_value);
    return 0;
}

