    // Exploit mechanism: Adding negative offset shifts pointers backward
    // beyond the allocated buffer boundary without bounds checking
    uint8_t *underflowed_cb = dest_cb + dct_offset;
    uint8_t *underflowed_cr = dest_cr + dct_offset;

